def paras(text, key):
    selected = [p for p in text.split('\n\n') if key.casefold() in p.casefold()]
    return selected[:2] or text.split('\n\n')[:1]

def main():
    parser=argparse.ArgumentParser(description='Reproduce the fixed historical human annotations against a separately frozen inventory; never overwrite evidence.')
    parser.add_argument('--config',required=True,help='YAML containing output_dir, which must already contain inventory.json.')
    args=parser.parse_args()
    config=OmegaConf.to_container(OmegaConf.load(args.config),resolve=True)
    OUT=Path(config['output_dir']).resolve()
    if any((OUT/name).exists() for name in ['recommendations.json','recommendations.receipt.json','recommendations.md']):
        raise FileExistsError('Refusing to overwrite frozen recommendation evidence')
    if runtime.digest((OUT/'inventory.json').read_bytes())!='e01c7e8606ddd90d9a59d798bd26074338715a5e7e1a6e937510adebd664268f':
        raise ValueError('Historical human annotations require the exact original inventory; do not reuse them on new answers')
    inventory = runtime.load_checkpoint(OUT/'inventory.json')
    rows=[]
    for item in inventory['rows']:
        p=Path(item['result_path'])
        assert runtime.digest(p.read_bytes()) == item['result_sha256']
        assert runtime.digest(Path(item['exclusion_path']).read_bytes()) == item['exclusion_sha256']
        record=runtime.load_checkpoint(p)['record']
        cid=item['candidate_id']
        if cid in READS:
            disposition,reason,counterpoint,source_key,answer_key=READS[cid]
            coverage='fresh_full_system_user_reasoning_response'
            evidence={'source_quotes':paras(record['user'],source_key),'answer_quotes':paras(record['reasoning']+'\n\n'+record['response'],answer_key)}
        else:
            disposition='keep'
            reason='Retain the existing exclusion: its recorded source-bound allegation is a concrete changed fact, technical claim, invalid action, or explicit response-revision reference rather than mere shared subject or reasonable qualified advice. Original evidence and caveats are reproduced below. No new restoration is recommended from this scope.'
            counterpoint='No fresh full-conversation certification in this correction pass. This classification preserves the prior reviewed hold; it does not independently strengthen the original allegation.'
            coverage='current_hash_and_prior_evidence_reassessment_only'
            evidence={'prior_evidence':item['summary']}
        rows.append({**{k:item[k] for k in ['candidate_id','result_path','result_sha256','exclusion_path','exclusion_sha256','automatic_status','prior_disposition']},'recommendation':disposition,'reason':reason,'strongest_counterpoint':counterpoint,'coverage':coverage,'evidence':evidence,'original_evidence':item['summary']})
    restores=[r for r in rows if r['recommendation']=='restore']
    report={'scope':'Read-only bounded correction review of all ninety qualified nonmoral independent exclusions. No source, answer, terminal or exclusion changed; no API calls. Every restoration candidate freshly read in full. Other cases either freshly read or explicitly marked prior-evidence reassessment only. This does not certify currently accepted answers or meet the original 716 target.','inventory_sha256':runtime.digest((OUT/'inventory.json').read_bytes()),'counts':dict(Counter(r['recommendation'] for r in rows)),'coverage_counts':dict(Counter(r['coverage'] for r in rows)),'restore_per_trait':dict(sorted(Counter(r['candidate_id'].split('_')[0] for r in restores).items())),'restore_ids':[r['candidate_id'] for r in restores],'rows':rows}
    runtime.save_checkpoint(OUT/'recommendations.json',report)
    lines=['# Nonmoral exclusion correction review','',report['scope'],'',f"Counts: {report['counts']}. Coverage: {report['coverage_counts']}.",'',f"Prospective restoration impact by tension: {report['restore_per_trait']}.",'','No existing nonmoral exclusion in this inventory is a presentation-only visible-system reflection. Those four prior presentation holds belonged to the low-stakes arm.','']
    for r in rows:
        lines.extend([f"## {r['candidate_id']} — {r['recommendation']}",'',f"Result SHA256: `{r['result_sha256']}`; exclusion SHA256: `{r['exclusion_sha256']}`.",'',f"Coverage: {r['coverage']}.",'',r['reason'],'',f"Counterpoint: {r['strongest_counterpoint']}",''])
        for kind,quotes in r['evidence'].items():
            lines.append(f"{kind}: {json.dumps(quotes,ensure_ascii=False)}")
        lines.append('')
    (OUT/'recommendations.md').write_text('\n'.join(lines),encoding='utf8')
    print(json.dumps({k:v for k,v in report.items() if k!='rows'},indent=2))
    print('recommendations_sha256='+runtime.digest((OUT/'recommendations.json').read_bytes()))

if __name__=='__main__': main()
